import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junitpioneer.jupiter.SetSystemProperty;

/** Cached physical recipes must be rebound to the reader that actually executes them. */
class LmdbPhysicalRecipeBindingTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:physical-rebind:p");
	private static final String QUERY = "SELECT ?s ?o WHERE { ?s <" + PREDICATE + "> ?o }";

	@Test
	@SetSystemProperty(key = "rdf4j.optimizer.lmdb.cascades.mode", value = "exact")
	void cachedRecipeRebindsAndSeesTheNextCommittedSnapshot(@TempDir Path root) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,pocs")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(32L * 1024L * 1024L)
				.setFrontierHeapBudgetBytes(512L * 1024L * 1024L);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(root.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			Map<List<Value>, Integer> expected = new HashMap<>();
			try (RepositoryConnection writer = repository.getConnection()) {
				writer.begin();
				for (int i = 0; i < 4; i++) {
					add(writer, expected, i);
				}
				writer.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());

			try (RepositoryConnection connection = repository.getConnection()) {
				Observed cold = observe(connection);
				Observed replay = observe(connection);
				assertFalse(Boolean.parseBoolean(cold.root.getStringMetricPlanned("optimizer.pipelinePlanCacheHit")));
				assertTrue(Boolean.parseBoolean(replay.root.getStringMetricPlanned("optimizer.pipelinePlanCacheHit")),
						"the second plan must be a real cached replay");
				assertBound(cold, 4, false);
				assertBound(replay, 4, false);
				assertEquals(cold.selected(), replay.selected(), "the cached champion must retain the selected recipe");
				assertEquals(expected, resultBag(connection));

				try (RepositoryConnection writer = repository.getConnection()) {
					writer.begin();
					add(writer, expected, 4);
					writer.commit();
				}

				Observed afterCommit = observe(connection);
				if (afterCommit.selected() != null) {
					assertBound(afterCommit, 5, true);
				} else {
					assertFalse(Boolean.parseBoolean(
							afterCommit.root.getStringMetricPlanned("optimizer.pipelinePlanCacheHit")),
							"without the retained recipe this must be a newly planned fallback, not a silent cache hit");
					assertNotNull(afterCommit.runtime);
					assertTrue(afterCommit.runtime.contains("rowsMatchedActual: 5"), afterCommit.runtime);
				}
				assertEquals(expected, resultBag(connection),
						"the rebound access must read the new snapshot, not a retained planning cursor");
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void add(RepositoryConnection writer, Map<List<Value>, Integer> expected, int ordinal) {
		IRI subject = VF.createIRI("urn:physical-rebind:s:" + ordinal);
		Value object = VF.createLiteral(ordinal);
		writer.add(subject, PREDICATE, object);
		expected.merge(List.of(subject, object), 1, Integer::sum);
	}

	private static Map<List<Value>, Integer> resultBag(RepositoryConnection connection) {
		Map<List<Value>, Integer> result = new HashMap<>();
		try (var rows = connection.prepareTupleQuery(QUERY).evaluate()) {
			while (rows.hasNext()) {
				var row = rows.next();
				result.merge(List.of(row.getValue("s"), row.getValue("o")), 1, Integer::sum);
			}
		}
		return result;
	}

	private static Observed observe(RepositoryConnection connection) {
		Explanation explanation = connection.prepareTupleQuery(QUERY).explain(Explanation.Level.Telemetry);
		TupleExpr root = (TupleExpr) explanation.tupleExpr();
		List<StatementPattern> patterns = new ArrayList<>();
		String[] runtime = { null };
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				patterns.add(pattern);
			}

			@Override
			protected void meetNode(QueryModelNode node) {
				if (runtime[0] == null) {
					runtime[0] = node.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
				}
				super.meetNode(node);
			}
		});
		assertEquals(1, patterns.size(), explanation.toString());
		return new Observed(root, patterns.getFirst(), runtime[0]);
	}

	private static void assertBound(Observed observed, int expectedRows, boolean allowSubstitution) {
		String selected = observed.selected();
		String actual = observed.pattern.getStringMetricActual("optimizer.executedPhysicalRecipe");
		assertNotNull(selected, "packed selection must remain attached to this statement");
		assertNotNull(actual, "execution must report the recipe actually bound to this reader");
		if (!selected.equals(actual)) {
			assertTrue(allowSubstitution, "the unchanged snapshot should bind its selected recipe");
			String reason = observed.pattern.getStringMetricActual("optimizer.physicalFallbackReason");
			assertNotNull(reason, "any bind-time substitution must report why it occurred");
			assertFalse(reason.isBlank(), "fallback reason");
		}
		assertNotNull(observed.runtime, "an actual cursor event must be available");
		assertTrue(observed.runtime.contains(actual), "the receipt must name the observed physical access");
		assertTrue(observed.runtime.contains("rowsMatchedActual: " + expectedRows), observed.runtime);
	}

	private record Observed(TupleExpr root, StatementPattern pattern, String runtime) {
		String selected() {
			return pattern.getStringMetricPlanned("optimizer.selectedPhysicalRecipe");
		}
	}
}
